128→			<p class="text-sm text-muted-foreground">
129→				{#if isStaticMode()}
130→					No workflow data available in the snapshot.
131→				{:else}
132→					Define workflows in <code class="text-xs bg-muted px-1 py-0.5 rounded">kynetic.meta.yaml</code> to see them here.
133→				{/if}
134→			</p>
135→		</div>
136→	{:else}
137→		<!-- AC: @ui-workflows-view ac-1 — Workflow cards with all required fields -->
138→		<div class="flex flex-col gap-3" data-testid="workflows-list">
139→			{#each workflows as workflow (workflow._ulid)}
140→				<Card class="transition-all duration-200 hover:shadow-md" data-testid="workflow-card">
141→					<CardHeader class="pb-3">
142→						<div class="flex items-start justify-between gap-4">
143→							<div class="flex-1 min-w-0">
144→								<div class="flex items-center gap-2 mb-1 flex-wrap">
145→									<h3 class="text-sm font-semibold" data-testid="workflow-id">
146→										{workflow.id}
147→									</h3>
148→									<!-- AC: @ui-workflows-view ac-1 — Trigger type badge -->
149→									<Badge variant="secondary" class="text-xs gap-1" data-testid="workflow-trigger">
150→										<ZapIcon class="h-3 w-3" />
151→										{workflow.trigger}
152→									</Badge>
153→									<!-- AC: @ui-workflows-view ac-1 — Loop variant indicator -->
154→									{#if workflow.mode === 'loop'}
155→										<Badge variant="outline" class="text-xs gap-1" data-testid="workflow-loop">
156→											<RepeatIcon class="h-3 w-3" />
157→											Loop
158→										</Badge>
159→									{/if}
160→									{#if workflow.based_on}
161→										<Badge variant="outline" class="text-xs gap-1" data-testid="workflow-variant">
162→											variant of @{workflow.based_on}
163→										</Badge>
164→									{/if}
165→									{#if workflow.enforcement === 'strict'}
166→										<Badge class="text-xs bg-status-blocked text-status-blocked-fg">
167→											Strict
168→										</Badge>
169→									{/if}
170→								</div>
171→								{#if workflow.description}
172→									<p class="text-sm text-muted-foreground whitespace-pre-line" data-testid="workflow-description">
173→										{workflow.description.trim()}
174→									</p>
175→								{/if}
176→							</div>
177→							<!-- AC: @ui-workflows-view ac-1 — Start button -->
178→							{#if !isStaticMode()}
179→								<Button
180→									variant="outline"
181→									size="sm"
182→									class="h-8 gap-1.5 text-xs shrink-0"
183→									data-testid="workflow-start-btn"
184→									onclick={() => copyStartCommand(workflow.id)}
185→								>
186→									{#if copiedId === workflow.id}
187→										<CopyIcon class="size-3.5" />
188→										Copied!
189→									{:else}
